namespace RecipeShare.Services;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = "";
    public string Category { get; set; } = "";
    public string Ingredients { get; set; } = "";
    public string Steps { get; set; } = "";
    public List<int> Ratings { get; set; } = new();

    public double AverageRating => Ratings.Count > 0 ? Ratings.Average() : 0;
}

public class RecipeService
{
    private readonly List<Recipe> _recipes = new()
    {
        new Recipe
        {
            Id = 1, Title = "Classic Margherita Pizza", Category = "Italian",
            Ingredients = "Pizza dough\nSan Marzano tomatoes\nFresh mozzarella\nFresh basil\nOlive oil\nSalt",
            Steps = "1. Preheat oven to 475°F.\n2. Roll out dough on a floured surface.\n3. Spread crushed tomatoes evenly.\n4. Tear mozzarella and distribute over sauce.\n5. Bake 10-12 minutes until crust is golden.\n6. Top with fresh basil and a drizzle of olive oil.",
            Ratings = new List<int> { 5, 4, 5 }
        },
        new Recipe
        {
            Id = 2, Title = "Spaghetti Carbonara", Category = "Italian",
            Ingredients = "Spaghetti\nGuanciale or pancetta\nEggs\nPecorino Romano\nBlack pepper",
            Steps = "1. Cook spaghetti in salted water until al dente.\n2. Crisp guanciale in a skillet.\n3. Whisk eggs with grated pecorino and pepper.\n4. Toss hot pasta with guanciale off heat.\n5. Add egg mixture, tossing quickly to coat without scrambling.",
            Ratings = new List<int> { 5, 5, 4, 5 }
        },
        new Recipe
        {
            Id = 3, Title = "Chicken Tikka Masala", Category = "Indian",
            Ingredients = "Chicken breast\nYogurt\nGaram masala\nTurmeric\nCumin\nTomato sauce\nHeavy cream\nGarlic\nGinger",
            Steps = "1. Marinate chicken in yogurt and spices for 1 hour.\n2. Grill or broil chicken until charred.\n3. Sauté garlic and ginger, add tomato sauce.\n4. Stir in garam masala, cumin, and turmeric.\n5. Add cream and simmer 10 minutes.\n6. Add chicken pieces and simmer 5 more minutes.",
            Ratings = new List<int> { 4, 5, 4 }
        },
        new Recipe
        {
            Id = 4, Title = "Vegetable Biryani", Category = "Indian",
            Ingredients = "Basmati rice\nMixed vegetables\nOnions\nYogurt\nBiryani spice mix\nSaffron\nMint\nCilantro\nGhee",
            Steps = "1. Soak rice for 30 minutes, then parboil.\n2. Fry sliced onions until golden.\n3. Layer vegetables, rice, fried onions, and herbs in a pot.\n4. Add saffron milk and ghee.\n5. Seal with foil and lid; cook on low heat 25 minutes.\n6. Gently fluff and serve.",
            Ratings = new List<int> { 5, 4 }
        },
        new Recipe
        {
            Id = 5, Title = "Beef Tacos", Category = "Mexican",
            Ingredients = "Ground beef\nTaco seasoning\nCorn tortillas\nLettuce\nTomato\nCheddar cheese\nSour cream\nSalsa",
            Steps = "1. Brown ground beef in a skillet.\n2. Add taco seasoning and water; simmer until thickened.\n3. Warm tortillas in a dry pan.\n4. Fill tortillas with beef.\n5. Top with lettuce, tomato, cheese, sour cream, and salsa.",
            Ratings = new List<int> { 4, 4, 3 }
        },
        new Recipe
        {
            Id = 6, Title = "Guacamole", Category = "Mexican",
            Ingredients = "Avocados\nLime juice\nCilantro\nRed onion\nJalapeño\nTomato\nSalt",
            Steps = "1. Halve avocados and remove pits.\n2. Mash avocado to desired consistency.\n3. Stir in diced onion, jalapeño, tomato, and cilantro.\n4. Add lime juice and salt to taste.\n5. Serve immediately with tortilla chips.",
            Ratings = new List<int> { 5, 5, 5, 4 }
        },
        new Recipe
        {
            Id = 7, Title = "Miso Ramen", Category = "Japanese",
            Ingredients = "Ramen noodles\nMiso paste\nChicken broth\nSoy sauce\nSesame oil\nSoft-boiled egg\nGreen onions\nCorn\nNori",
            Steps = "1. Bring chicken broth to a simmer.\n2. Whisk in miso paste, soy sauce, and sesame oil.\n3. Cook ramen noodles separately according to package.\n4. Place noodles in a bowl, ladle broth over them.\n5. Top with soft-boiled egg, green onions, corn, and nori.",
            Ratings = new List<int> { 5, 4, 5 }
        },
        new Recipe
        {
            Id = 8, Title = "Chocolate Chip Cookies", Category = "Desserts",
            Ingredients = "Butter\nSugar\nBrown sugar\nEggs\nVanilla extract\nFlour\nBaking soda\nSalt\nChocolate chips",
            Steps = "1. Cream butter and sugars until fluffy.\n2. Beat in eggs and vanilla.\n3. Mix flour, baking soda, and salt; add to wet ingredients.\n4. Fold in chocolate chips.\n5. Scoop onto baking sheets.\n6. Bake at 375°F for 9-11 minutes until edges are golden.",
            Ratings = new List<int> { 5, 5, 4, 5, 5 }
        },
    };

    private int _nextId = 9;

    public IReadOnlyList<Recipe> GetAll() => _recipes.AsReadOnly();

    public IReadOnlyList<string> GetCategories() =>
        _recipes.Select(r => r.Category).Distinct().OrderBy(c => c).ToList();

    public IReadOnlyList<Recipe> GetByCategory(string category) =>
        _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();

    public Recipe? GetById(int id) => _recipes.FirstOrDefault(r => r.Id == id);

    public void AddRating(int recipeId, int stars)
    {
        var recipe = GetById(recipeId);
        if (recipe is not null && stars is >= 1 and <= 5)
        {
            recipe.Ratings.Add(stars);
        }
    }

    public void AddRecipe(string title, string category, string ingredients, string steps)
    {
        _recipes.Add(new Recipe
        {
            Id = _nextId++,
            Title = title,
            Category = category,
            Ingredients = ingredients,
            Steps = steps,
        });
    }
